-- New default avatars for Codex (the classic white icon: black OpenAI
-- knot on white) and Cursor (its own app icon), with theme colours that match (Codex light gray,
-- Cursor ink). Only Bots still showing the previous default image change; an avatar the user
-- picked, and its colour, stay as they are. Avatar images live in settings as JSON strings.
UPDATE bots SET avatar_color = 'gray'
WHERE id IN (SELECT bot_id FROM external_agent_bots WHERE agent_id = 'codex')
  AND (SELECT value FROM settings WHERE key = 'avatar:bot:' || bots.id) = json_quote('data:image/png;base64,');
UPDATE settings SET value = json_quote('data:image/png;base64,')
WHERE value = json_quote('data:image/png;base64,')
  AND key IN (SELECT 'avatar:bot:' || bot_id FROM external_agent_bots WHERE agent_id = 'codex');
UPDATE bots SET avatar_color = 'ink'
WHERE id IN (SELECT bot_id FROM external_agent_bots WHERE agent_id = 'cursor')
  AND (SELECT value FROM settings WHERE key = 'avatar:bot:' || bots.id) = json_quote('data:image/png;base64,');
UPDATE settings SET value = json_quote('data:image/png;base64,')
WHERE value = json_quote('data:image/png;base64,')
  AND key IN (SELECT 'avatar:bot:' || bot_id FROM external_agent_bots WHERE agent_id = 'cursor');
